CREATE TABLE academy_teachers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, subject VARCHAR(180), bio TEXT, email VARCHAR(254), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE academy_lessons (id BIGINT PRIMARY KEY AUTO_INCREMENT, course_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, body TEXT, resource_url VARCHAR(1000), position_number INT NOT NULL DEFAULT 0, published BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT fk_lesson_course FOREIGN KEY(course_id) REFERENCES portal_courses(id));
CREATE TABLE academy_certificates (id BIGINT PRIMARY KEY AUTO_INCREMENT, enrollment_id BIGINT NOT NULL UNIQUE, issued_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), certificate_code VARCHAR(80) NOT NULL UNIQUE, CONSTRAINT fk_certificate_enrollment FOREIGN KEY(enrollment_id) REFERENCES portal_enrollments(id));
CREATE TABLE academy_site_content (id BIGINT PRIMARY KEY AUTO_INCREMENT, content_key VARCHAR(120) NOT NULL UNIQUE, content_value TEXT NOT NULL);
CREATE TABLE academy_notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NULL, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES portal_users(id));
